"Digit4","Digit5","Digit6","Digit7","Digit8","Digit9","ScrollLock","AltRight","Escape","gas_type","gas_quantity","sounds/gas.mp3","no_steal","failed_steal","stole_item","level_up","BREW","ENERGIZE","warm_up","need_to_equip","not_ready","need_energy","energize_1","energize_all","energize_desc","desc_hint","desc_warming","thrown_dust","sell","energize","sell_1","sell_all","visible","inactive","FADE_IN","STATIC","FADE_OUT","[IntBuffer position=","fonts/pixel_font.png","interfaces/surface.png","empower_desc","no_pit",
